type View = "Overview" | "People" | "Academics" | "Attendance" | "Finance & Resources" | "Timetable Generator" | "Reports" | "Administration" | "NEXUS AI" | "Learners" | "Assessments" | "Teacher Allocations" | "Report Cards" | "Timetable" | "Alumni" | "Communication" | "Users" | "School Settings" | "Audit Log" | "Backend & Data";
