type Role = "Super Admin" | "Administrator" | "Teacher" | "Bursar" | "Storekeeper";
const staffRoleLabel = (role: string) => ({ super_admin: "Head Teacher", admin: "Deputy", teacher: "Teacher", class_teacher: "Class Teacher", senior_teacher: "Senior Teacher", deputy_head: "Deputy", head_teacher: "Head Teacher", finance: "Bursar", storekeeper: "Storekeeper", other: "Teacher" }[role] ?? "Teacher");
